#!/usr/bin/env python3
"""Source-specific sarcoma education; numbers describe NCCP schedules, not orders."""
import copy
DATE='2026-11-18'
NCI='https://www.cancer.gov/types/soft-tissue-sarcoma/hp/adult-soft-tissue-treatment-pdq'
GEDDIS='https://pmc.ncbi.nlm.nih.gov/articles/PMC5622179/'
EORTC='https://pubmed.ncbi.nlm.nih.gov/24618336/'
DTIC='https://pubmed.ncbi.nlm.nih.gov/1868027/'
PRODUCTS={
 'doxorubicin':('HPRA doxorubicin product information','https://assets.hpra.ie/products/Human/29006/Licence_PA22766-004-001_01022023144327.pdf'),
 'ifosfamide':('HPRA ifosfamide product information','https://assets.hpra.ie/products/Human/15731/Licence_PA2299-028-001_11092023124600.pdf'),
 'gemcitabine':('HPRA gemcitabine product information','https://assets.hpra.ie/products/Human/28076/Licence_PA2059-039-001_04062024175114.pdf'),
 'docetaxel':('EMA Taxotere product information','https://www.ema.europa.eu/en/documents/product-information/taxotere-epar-product-information_en.pdf'),
 'dacarbazine':('HPRA dacarbazine product information','https://assets.hpra.ie/products/Human/29355/Licence_PA1760-001-001_31052024114641.pdf')}
SOURCES={
 '00500':dict(catalogue_url='https://healthservice.hse.ie/documents/6738/500_V3_DOXOrubicin_75.pdf',pages=4),
 '00391':dict(catalogue_url='https://healthservice.hse.ie/documents/6730/391_DOXOrubicin_60_and_Ifosfamide.pdf',pages=6),
 '00392':dict(catalogue_url='https://healthservice.hse.ie/documents/6731/392_DOXOrubicin_75_and_ifosfamide.pdf',pages=6),
 '00501':dict(catalogue_url='https://healthservice.hse.ie/documents/6739/501_V4_Gemcitabine_DOCEtaxel.pdf',pages=6),
 '00511':dict(catalogue_url='https://healthservice.hse.ie/documents/6741/511_V2_Dacarbazine.pdf',pages=3)}
WIDER='A sarcoma multidisciplinary team reviews the exact pathology, disease extent, prior treatment, fitness and your priorities. Surgery and radiotherapy may help local control in selected circumstances; their role and timing are decided separately. Chemotherapy does not automatically replace an operation or radiotherapy. Supportive and palliative care can be used alongside cancer treatment to help symptoms and daily life.'
ACCESS='The team chooses suitable intravenous access and explains line care. Tell the nurse immediately about burning, pain, redness or swelling during an injection or drip. Do not wait for the visit to finish. If you have a port or PICC, agree dressing, flushing and removal arrangements.'
FERTILITY='Discuss fertility preservation before treatment. Avoid pregnancy and breastfeeding as directed. Your team must give written contraception and post-treatment precautions for every medicine, using current product information; the required duration may differ by medicine and between patients.'
GENERIC='Discuss low blood counts with serious infection or sepsis, anaemia and bleeding; nausea or vomiting; mouth soreness, appetite or taste change, diarrhoea or constipation; tiredness, hair and skin changes; infusion reactions and intravenous-line complications; fertility, pregnancy and breastfeeding effects; and the possibility of lasting organ injury, rare later cancers or death from serious treatment complications. Risks differ between medicines and people. The medicine-specific section explains the main additional risks for this regimen.'

def agents(agent_from):
 out={key:copy.deepcopy(agent_from(code,key))for code,key in [('00333','doxorubicin'),('00602','ifosfamide'),('00281','gemcitabine'),('00204','docetaxel'),('00464','dacarbazine')]}
 out['doxorubicin'].update(type='Anthracycline chemotherapy',alias='',watch='Report breathlessness, chest pain, palpitations or ankle swelling promptly. Tell the nurse immediately about pain or burning at the infusion site. Red urine can occur briefly after the dose; painful urination, clots or persistent redness need assessment.',risks=['Low blood counts, serious infection or sepsis, anaemia and bleeding','Nausea, vomiting, mouth ulcers, hair loss and fatigue','Heart muscle damage or rhythm problems; heart damage may appear later and can be permanent','Severe tissue injury if the medicine leaks outside the vein','Fertility and pregnancy harm; rare later leukaemia or other blood cancers'])
 out['ifosfamide'].update(visual=['DNA cross-links form','Cell division is disrupted','Bladder, kidney and brain checks'],risks=['Low blood counts, serious infection or sepsis, anaemia and bleeding','Bladder inflammation or bleeding; kidney damage and electrolyte loss, sometimes lasting','Brain effects causing confusion, unusual sleepiness, hallucinations or seizures','Nausea, vomiting, mouth soreness, hair loss and fatigue','Fertility and pregnancy harm; rare serious heart or lung injury and later cancers'])
 out['gemcitabine'].update(risks=['Low blood counts, serious infection, anaemia and bleeding','Nausea, fatigue, flu-like symptoms, mouth soreness, rash and swelling','Liver-test changes; occasionally serious liver injury','Rare serious lung inflammation, fluid leakage from blood vessels or kidney injury with breakdown of red cells','Rare severe skin reactions or a brain syndrome causing headache, seizures or visual changes; fertility and pregnancy harm'],watch='Report fever, breathlessness, new widespread rash, rapid swelling, reduced urine, unusual bruising or severe headache with visual change or confusion urgently.')
 out['docetaxel'].update(risks=['Low blood counts, infection or sepsis; severe bowel inflammation may occur with or without low white cells','Hair loss, which can sometimes persist; mouth soreness, fatigue and nail changes','Numbness, tingling or weakness from nerve injury, sometimes lasting','Fluid retention, swelling and allergic infusion reactions despite premedication','Rare severe skin reactions, lung inflammation or sight-threatening eye effects; fertility and pregnancy harm'],watch='Take the prescribed dexamethasone before docetaxel. Report fever, severe abdominal pain or diarrhoea, breathlessness, swelling, persistent numbness or new blurred vision promptly. Tell staff immediately about any infusion reaction.')
 out['dacarbazine'].update(visual=['Activated in the body','DNA damage limits division','Blood and liver checks'],risks=['Nausea and vomiting; appetite loss and fatigue','Low blood counts with infection, anaemia or bleeding; counts may fall several weeks after a dose','Infusion-site pain and tissue injury if medicine leaks outside the vein','Rare severe liver injury, including blocked small liver veins; severe allergic reactions','Photosensitivity, hair loss and flu-like symptoms; fertility and pregnancy harm; rare later cancers'],watch='Report fever, bleeding, persistent vomiting, severe upper abdominal pain, new jaundice or rapidly increasing abdominal swelling urgently. Tell the nurse about burning at the infusion site.')
 for key,a in out.items():a['source_ids']=['nccp',key+'-pi']
 return out

def anatomy(names,ifos=False,gemdoc=False,dtic=False):
 if gemdoc:return [
 ['mouth','Mouth and appetite',names,'Mouth soreness, taste changes and nausea can affect drinking and nutrition. Ask early for mouth care and symptom support.',50,13],
 ['lungs','Breathing',names,'New cough or breathlessness needs prompt assessment for infection, lung inflammation or fluid effects.',61.5,24.7],
 ['liver','Liver',names,'Blood tests help detect liver changes. Report yellow eyes, dark urine or new significant abdominal pain.',43,33],
 ['kidneys','Kidneys',names,'Gemcitabine can rarely cause serious kidney and blood-cell injury. Report reduced urine, swelling or unusual bruising.',39.5,38.6],
 ['blood','Blood cells',names,'Low white cells increase infection risk, low red cells cause tiredness, and low platelets cause bleeding. Fever or sudden illness needs immediate contact.',64,55],
 ['bowel','Bowel',names,'Report severe abdominal pain, persistent diarrhoea or blood in stools immediately; docetaxel can rarely cause serious bowel inflammation.',50,44.5],
 ['skin','Skin, hair and nails',names,'Rash, hair loss, nail changes and swelling can occur. Blistering or peeling skin needs urgent help.',65,70],
 ['nerves','Hands and feet','Docetaxel','Report numbness, tingling, pain or weakness before the next dose; nerve symptoms may last after treatment.',35,77]]
 rows=[
 ['mouth','Mouth and appetite',names,'Soreness, nausea or vomiting can reduce eating and drinking. Use the prescribed anti-sickness plan and ask early for help.',50,13],
 ['liver','Liver',names,'Liver blood tests help guide safe treatment. New jaundice or severe upper abdominal pain needs urgent assessment.',43,33],
 ['blood','Blood cells',names,'Low blood counts can cause infection, anaemia or bleeding. Fever, shaking chills or sudden illness needs immediate contact.',64,55],
 ['bowel','Bowel',names,'Constipation or diarrhoea can follow treatment or support medicines. Report persistent symptoms, severe pain or inability to drink.',50,44.5],
 ['skin','Skin, hair and vein',names,'Hair loss and skin changes may occur. Pain or burning where treatment enters the vein must be reported immediately.',65,70],
 ['whole','Energy and fertility',names,'Fatigue may persist between visits. Discuss fertility preservation and pregnancy precautions before treatment.',35,77]]
 if dtic:
  rows[1]=['kidneys','Kidney function',names,'Kidney blood tests help the team choose a safe dose. Tell the team if drinking is difficult or urine falls.',39.5,38.6]
  return [['brain','Feeling unwell',names,'Flu-like symptoms can follow treatment, but do not assume fever is harmless: contact oncology immediately.',50,8]]+rows+[['liver-alert','Liver warning signs',names,'Dacarbazine rarely causes rapidly serious liver injury. Severe abdominal pain, yellow eyes or increasing abdominal swelling need urgent assessment.',61,35]]
 if ifos:rows.insert(0,['brain','Brain','Ifosfamide','Confusion, unusual drowsiness, hallucinations or seizures may be treatment-related and need immediate assessment.',50,8]);rows.insert(2,['heart','Heart','Doxorubicin','Heart effects can occur during treatment or later. Report new breathlessness, ankle swelling, chest pain or palpitations.',48,25]);rows.insert(4,['kidneys','Kidneys and bladder','Ifosfamide','Mesna and prescribed fluids protect the bladder. Blood in urine, reduced urine or new weakness needs urgent assessment; mesna does not prevent all kidney or brain injury.',39.5,38.6])
 else:rows.insert(1,['heart','Heart','Doxorubicin','Heart effects can occur during treatment or later. Previous anthracycline doses matter. Report new breathlessness, ankle swelling, chest pain or palpitations.',48,25]);rows.insert(3,['kidneys','Urine colour','Doxorubicin','Urine may briefly look red after treatment. Pain, clots or persistent redness is not assumed to be harmless and needs assessment.',39.5,38.6])
 return [row for row in rows if row[0]!='liver'] if ifos else rows

def facts(agent_from):
 a=agents(agent_from);out={}
 dox=dict(title='Doxorubicin for soft tissue sarcoma',context='Locally advanced unresectable or metastatic soft tissue sarcoma',purpose='The aim is usually to control advanced sarcoma, reduce cancer-related symptoms or slow growth. Your consultant explains the realistic goal for your own tumour and circumstances.',days=21,kind='cycle',label='Doxorubicin day 1, every 21 days',agents=[a['doxorubicin']],anatomy=anatomy('Doxorubicin'),schedule='NCCP 00500 gives doxorubicin 75 mg/m² on day 1 of a 21-day cycle, usually for 3–6 cycles. The source allows consideration of 60 mg/m² in people over 70; the prescribed dose and number of cycles are individual decisions.',administration='Doxorubicin is given intravenously on day 1 by trained staff through suitable venous access. Blood tests, review, anti-sickness medicines and observation make the whole visit longer than the injection itself.',baseline='Full blood count, kidney and liver tests, ECG, mouth and throat assessment and review of prior anthracycline exposure. Heart ultrasound or MUGA is required by the source when over 65 or otherwise indicated; the source baseline LVEF criterion is at least 50%.',monitoring='Blood count and kidney/liver tests before each cycle, with review of infection, mouth symptoms and cumulative doxorubicin exposure. Additional heart assessment follows clinical risk and symptoms.',support='This is a high nausea/vomiting-risk treatment. Use one written prevention and rescue plan before and after treatment. Confirm any prescribed stomach protection and local mouth-care measures; do not add duplicate support courses.',prep='No separate routine drug premedication is specified by NCCP, but prescribed anti-sickness treatment is required. Review all medicines, prior anthracyclines, heart symptoms and pregnancy/fertility plans before starting.',access=ACCESS,wider=WIDER,scope='This is the 75 mg/m² single-agent NCCP 00500 schedule. It is different from the divided-dose doxorubicin/ifosfamide schedules. Lifetime anthracycline exposure and cardiac risk may limit further treatment.',trial='GeDDiS: first-line chemotherapy in advanced soft tissue sarcoma',trial_url=GEDDIS,evidence='In GeDDiS, first-line doxorubicin 75 mg/m² every three weeks was compared with gemcitabine 675 mg/m² on days 1 and 8 plus docetaxel 75 mg/m² on day 8. The combination did not improve progression-free or overall survival over doxorubicin in the study population.',caveat='This trial informs a treatment discussion for previously untreated advanced soft tissue sarcoma. It does not predict an individual response, establish a benefit for every sarcoma subtype or determine later-line treatment.',doses=[('doxorubicin','Doxorubicin',1,1,'Doxorubicin is given after safety review and prescribed anti-sickness medicines.')],phases=[('day1','Day 1: doxorubicin',['Doxorubicin'],'high')],course='3–6 cycles, individually confirmed',urgent='New breathlessness, chest pain, palpitations or ankle swelling needs prompt assessment. Pain or burning at the infusion site requires immediate nursing review.')
 out['00500']=dox
 for code,dose in [('00391',20),('00392',25)]:
  f=copy.deepcopy(dox);total=dose*3
  f.update(title=f'Doxorubicin {total} mg/m² and ifosfamide for sarcoma',context='High-risk soft tissue sarcoma before surgery, or advanced/metastatic soft tissue sarcoma'if code=='00392'else'Locally advanced unresectable or metastatic soft tissue sarcoma',purpose='Your team may choose a combination when reducing tumour size is an important goal and you are fit for more intensive treatment. '+('For high-risk disease before surgery, the goal and local-treatment plan require specialist sarcoma review; for advanced disease, treatment generally aims at control and symptom relief.'if code=='00392'else'For advanced disease, treatment generally aims at control and symptom relief; a combination is not a guarantee of longer survival.'),label=f'Doxorubicin {total} mg/m² total + ifosfamide, days 1–3 every 21 days',agents=[copy.deepcopy(a['doxorubicin']),copy.deepcopy(a['ifosfamide'])],anatomy=anatomy('Doxorubicin and ifosfamide',ifos=True),schedule=f'NCCP {code}: doxorubicin {dose} mg/m² and ifosfamide 3000 mg/m² on each of days 1–3, repeated every 21 days for up to 6 cycles. Per-cycle totals are doxorubicin {total} mg/m² and ifosfamide 9000 mg/m². Mesna, hydration and other support continue for their prescribed periods.',administration='Each treatment day includes intravenous doxorubicin followed by a 3-hour ifosfamide infusion, with prescribed mesna and fluids. Mesna includes a prolonged infusion and hydration continues after chemotherapy; the service confirms admission, pump arrangements and the actual finish time.',baseline='Full blood count, kidney and liver tests, ECG and prior anthracycline review. ECHO/MUGA when over 65 or clinically indicated; the source baseline LVEF criterion is above 50%. Review renal, neurological and urinary risks and whether the complete fluid/support programme is suitable.',monitoring='Blood count and kidney/liver tests before each cycle. Neurological assessment before every ifosfamide dose; check for blood in urine before each dose and every 8 hours on treatment days. Monitor fluid balance, urine output and electrolytes according to the individual plan.',support='Mesna and prescribed hydration are essential bladder protection. NCCP requires G-CSF support and proton-pump inhibitor prophylaxis for this regimen; the team specifies product, dose and timing. Multi-day anti-sickness treatment needs a single reconciled prescription. Aprepitant may increase ifosfamide-related brain toxicity, so pharmacy must check the chosen plan.',prep='Confirm the full three-day treatment and post-treatment mesna/fluid plan, G-CSF injections, stomach protection and anti-sickness medicines before starting. Tell the team about sedating medicines or new confusion. Do not change fluid intake or medicines without the team’s advice.',access=ACCESS+' Confirm who manages the mesna pump and when it is disconnected; do not alter pump settings yourself.',scope=f'This is NCCP {code}: doxorubicin {total} mg/m² and ifosfamide 9 g/m² per cycle. The two NCCP combination regimens have different doxorubicin doses and eligibility details. They must not be substituted for each other or for a published 10 g/m² ifosfamide regimen.',trial='EORTC 62012: doxorubicin with or without intensified ifosfamide',trial_url=EORTC,evidence='In a first-line advanced soft tissue sarcoma trial, adding intensified ifosfamide increased tumour response and delayed progression, but did not demonstrate a statistically significant overall-survival advantage and caused substantially more toxicity. This helps explain why a combination may be considered when tumour shrinkage is especially important.',caveat=f'The trial used doxorubicin 75 mg/m² with ifosfamide 10 g/m² over four days. NCCP {code} uses doxorubicin {total} mg/m² with ifosfamide 9 g/m² over three days. Trial response or survival figures are not validated estimates for this exact schedule. The advanced-disease trial does not establish neoadjuvant benefit.',doses=[('doxorubicin','Doxorubicin',1,3,f'Doxorubicin {dose} mg/m² each day, total {total} mg/m² per cycle.'),('ifosfamide','Ifosfamide',1,3,'Ifosfamide 3000 mg/m² each day over 3 hours. Mesna, fluids and safety checks accompany treatment.')],phases=[('days1to3','Days 1–3: doxorubicin and ifosfamide',['Doxorubicin','Ifosfamide'],'high')],course='Up to 6 cycles, individually confirmed',urgent='Confusion, unusual sleepiness, hallucinations, seizures, blood in urine or very little urine requires immediate assessment. New breathlessness or swelling also needs urgent advice.')
  out[code]=f
 out['00501']=dict(title='Gemcitabine and docetaxel for soft tissue sarcoma',context='Locally advanced unresectable or metastatic soft tissue sarcoma',purpose='The treatment aims to control advanced sarcoma and help cancer-related symptoms. The choice depends on sarcoma subtype, previous treatment, fitness and your priorities; your consultant explains why this combination is being considered.',days=21,kind='cycle',label='Gemcitabine days 1 and 8; docetaxel day 8; repeat every 21 days',agents=[a['gemcitabine'],a['docetaxel']],anatomy=anatomy('Gemcitabine and docetaxel',gemdoc=True),schedule='NCCP 00501 gives gemcitabine 675 mg/m² on days 1 and 8, with docetaxel 75 mg/m² on day 8. Repeat every 21 days for up to 6 cycles if suitable. Day 8 has its own safety review and can be delayed or omitted on clinical advice.',administration='Gemcitabine is infused over 90 minutes on both days 1 and 8. On day 8 it is followed by docetaxel over 60 minutes. Allow additional time for blood tests, review, line care and observation.',baseline='Full blood count, kidney and liver tests and bone profile. Review infection, breathing symptoms, previous drug reactions, existing neuropathy, fluid retention and the planned steroid prescription.',monitoring='Check blood counts for both day 1 and day 8 decisions; day-specific thresholds differ. Kidney and liver tests are reviewed before each cycle and more often when indicated. Review breathing, swelling, skin, bowel symptoms and numbness before further treatment.',support='Take dexamethasone 8 mg by mouth twice daily for 3 days, starting day 7, unless your team prescribes an explicitly revised plan; NCCP requires at least 3 doses before docetaxel. This reduces allergic reactions and fluid retention. Both drugs have low emetogenic classification in this source. G-CSF may be used based on the prescribed risk plan; it is not mandatory for every patient in NCCP 00501.',prep='Get the day 7–9 dexamethasone prescription before the day 8 visit. Contact the team if doses were missed or vomited; do not silently double doses. Review diabetes control, infection symptoms and all medicines. Reconcile steroid premedication with any anti-sickness steroids.',access=ACCESS,wider=WIDER,scope='This is the gemcitabine 675 mg/m², 90-minute sarcoma schedule. It must not be replaced by a 1000 mg/m² or 30-minute gemcitabine schedule from another regimen. The sarcoma use described by this source is off-label and requires a documented discussion and consent under local policy.',trial='GeDDiS: gemcitabine/docetaxel versus doxorubicin',trial_url=GEDDIS,evidence='GeDDiS tested these gemcitabine/docetaxel doses and infusion durations against doxorubicin 75 mg/m² in previously untreated advanced soft tissue sarcoma. The combination did not improve progression-free or overall survival and was harder to deliver. The study did not show a clear superior effect in a particular histological subgroup.',caveat='A first-line comparison does not establish the best later-line choice for every sarcoma subtype. Individual suitability and prior treatment matter. Do not import growth-factor schedules or supportive orders from the trial into the NCCP regimen automatically.',doses=[('gemcitabine1','Gemcitabine',1,1,'Gemcitabine 675 mg/m² over 90 minutes after day 1 safety review.'),('gemcitabine8','Gemcitabine',8,8,'Gemcitabine 675 mg/m² over 90 minutes after the separate day 8 review.'),('docetaxel','Docetaxel',8,8,'Docetaxel 75 mg/m² over 60 minutes after gemcitabine. Check dexamethasone premedication.')],phases=[('day1','Day 1: gemcitabine',['Gemcitabine'],'low'),('day8','Day 8: gemcitabine and docetaxel',['Gemcitabine','Docetaxel'],'low')],course='Up to 6 cycles, individually confirmed',urgent='New breathlessness, reduced urine, severe abdominal pain or diarrhoea, widespread blistering rash, rapid swelling or new visual symptoms needs urgent assessment. Fever is never assumed to be only a flu-like drug effect.')
 out['00511']=dict(title='Dacarbazine for metastatic soft tissue sarcoma',context='Metastatic soft tissue sarcoma',purpose='Dacarbazine may be used to control metastatic sarcoma and help symptoms. Expected benefit depends on tumour subtype, previous treatment and your overall condition; your consultant explains why this option is appropriate.',days=21,kind='cycle',label='Dacarbazine day 1, every 21 days',agents=[a['dacarbazine']],anatomy=anatomy('Dacarbazine',dtic=True),schedule='NCCP 00511 gives dacarbazine 1.2 g/m² on day 1 every 21 days. The source describes 4 cycles or treatment until progression or unacceptable toxicity; your consultant must specify the planned duration and review point.',administration='Dacarbazine is infused intravenously over 1 hour with protection from light. The total visit also includes safety review, prescribed anti-sickness medicines and observation.',baseline='Full blood count and kidney/liver tests; review liver disease, prior treatment and interacting medicines. Discuss fertility, pregnancy prevention and the planned high-risk anti-sickness support.',monitoring='Full blood count and kidney/liver tests before each treatment. Counts can fall several weeks after a dose, so report infection or bleeding even late in the cycle; symptoms or previous low counts may require extra tests.',support='This is a high nausea/vomiting-risk treatment. Follow the prescribed prevention, delayed-sickness and rescue plan, and contact the team if vomiting prevents drinking. Confirm any stomach protection and local mouth care. Avoid alcohol and have the team review potentially liver-toxic medicines and phenytoin.',prep='NCCP lists no separate routine premedication or additional regimen-specific prophylaxis, but anti-sickness treatment is required. Bring an up-to-date medicine list and report new abdominal pain, jaundice, fever or bleeding before treatment.',access=ACCESS,wider=WIDER,scope='This is dacarbazine 1.2 g/m² over 1 hour, not the 1 g/m² comparator used in some later trials. The current catalogue-linked NCCP document is version 2, reviewed March 2021 with a printed review-due date in March 2026; the treating team should confirm the current local protocol.',trial='Historical EORTC phase II study of high-dose dacarbazine',trial_url=DTIC,evidence='A small historical single-arm EORTC study evaluated dacarbazine 1.2 g/m² every three weeks after prior chemotherapy and observed responses in some patients. It supports activity in that setting but does not show a survival advantage over another treatment.',caveat='The historical study used a 20-minute infusion, whereas NCCP 00511 specifies 1 hour. Its small, previously treated population and lack of a randomised comparator limit inference. Do not copy response or survival figures from studies using 1 g/m² or mixed dacarbazine doses as estimates for this exact regimen.',doses=[('dacarbazine','Dacarbazine',1,1,'Dacarbazine 1.2 g/m² over 1 hour with light protection, after safety review and anti-sickness treatment.')],phases=[('day1','Day 1: dacarbazine',['Dacarbazine'],'high')],course='Individual plan: source states 4 cycles or until progression/unacceptable toxicity',urgent='Severe upper abdominal pain, jaundice, rapidly increasing abdominal swelling, persistent vomiting or bleeding needs urgent assessment. Report burning at the infusion site immediately.')
 return out
